for b in /workspace/dataset/test6_executable /output/test6; do echo "== $b"; timeout 20 perl nul.pl "$b" > o.tmp 2> e.tmp; echo "exit=$?"; od -c o.tmp; echo "stderrbytes=$(stat -c%s e.tmp)"; done

cd /tmp/w-argv && cat > exe.c <<'EOF'
#include <unistd.h>
#include <stdio.h>
#include <string.h>
/* usage: exe MODE binary [args...]
   MODE=0 -> argv is completely empty (argc==0)
   MODE=1 -> argv[0] only, no argv[1]
   MODE=2 -> argv[0]="", argv[1]=<raw bytes from arg3 as-is>
*/
int main(int argc, char **argv) {
    int mode = atoi(argv[1]);
    char *bin = argv[2];
    if (mode == 0) { char *av[] = { NULL }; execv(bin, av); }
    else if (mode == 1) { char *av[] = { bin, NULL }; execv(bin, av); }
    else { char *av[] = { "", argv[3], NULL }; execv(bin, av); }
    perror("execv"); return 127;
}
EOF
gcc -w -o exe exe.c && echo built

cd /tmp/w-argv && cat > fuzz.pl <<'PERL'
use strict; use warnings;
my $C='/workspace/dataset/test6_executable'; my $R='/output/test6';
my @alpha = (0x30..0x39, 0x2b, 0x2d, 0x20, 0x09, 0x0a, 0x0d, 0x0b, 0x0c,
             0xff, 0xfe, 0x80, 0xc0, 0xc2, 0xc3, 0xe0, 0xe2, 0xed, 0xf0, 0xf4, 0xf5, 0xa0, 0x2e, 0x78, 0x61);
srand(1234);
my ($cases,$bad)=(0,0);
for my $it (1..500) {
  my $len = 1 + int(rand(4));
  my $arg = join('', map { chr($alpha[int(rand(scalar @alpha))]) } 1..$len);
  my ($co,$ce,$cx) = run($C,$arg);
  my ($ro,$re,$rx) = run($R,$arg);
  $cases++;
  if ($co ne $ro or $ce ne $re or $cx != $rx) {
    $bad++;
    printf "MISMATCH arg=%s\n  cpp exit=%d out=%s err=%s\n  rst exit=%d out=%s err=%s\n",
      unpack("H*",$arg), $cx, unpack("H*",substr($co,0,80)), $ce, $rx, unpack("H*",substr($ro,0,80)), $re;
  }
}
printf "fuzz: %d cases, %d mismatches\n", $cases, $bad;
sub run {
  my ($bin,$arg)=@_;
  my $pid = open(my $fh, "-|");
  die "fork" unless defined $pid;
  if ($pid == 0) { open(STDERR,">","/tmp/w-argv/fz.err"); exec { $bin } ($bin,$arg); exit 127; }
  local $/; my $out = <$fh> // ''; close($fh); my $x = $?;
  open(my $eh,"<","/tmp/w-argv/fz.err"); local $/; my $err = <$eh> // ''; close $eh;
  return ($out,$err,$x);
}
PERL
timeout 570 perl fuzz.pl 2>&1 | tail -20
